.FromCardCompat(this, play).TargetingAllOpponents(cs)
.WithHitCount(hits)
.WithHitVfxNode(NGrandFinaleImpactVfx.Create)
.WithHitFx(null, null, "blunt_attack.mp3")
.Execute(ctx);
}
}
